    if(value==='exceptional-2')return {id:'exceptional-2',title:'Bulletin exceptionnel de salaire · 2',label:'Bulletins exceptionnels de salaire · modèle 2'};
    return {id:'ordinary',title:'Bulletin de salaire',label:'Bulletin de salaires'};
