    var script="<script>(function(){var tooSmall=false;function fit(){tooSmall=false;document.querySelectorAll('.slip-print-page').forEach(function(page){var doc=page.querySelector('.slip-edition-document');doc.style.transform='none';var scale=Math.min(1,(page.clientHeight-12)/doc.scrollHeight,(page.clientWidth-2)/doc.scrollWidth);doc.style.transform='scale('+scale+')';if(scale<0.65)tooSmall=true;});var warning=document.getElementById('slip-scale-warning');warning.textContent=tooSmall?'Attention : un bulletin contient beaucoup de données et sera fortement réduit pour tenir sur une page. Vérifiez sa lisibilité avant impression.':'';}window.addEventListener('load',fit);window.addEventListener('beforeprint',fit);document.getElementById('slip-print-button').addEventListener('click',function(){fit();if(!tooSmall||window.confirm('Un bulletin sera fortement réduit pour tenir sur une page. Continuer ?'))window.print();});})();<\/script>";
